from pathlib import Path
import json, html
root=Path(__file__).parent
sources=[
 {'id':'S01','organization':'NIST','title':'Phishing — CSRC Glossary','url':'https://csrc.nist.gov/glossary/term/phishing','topic':'基礎定義','summary':'網路釣魚是一種數位社交工程：攻擊者使用看似真實的假訊息，要求使用者提供資料或前往假網站。','points':['釣魚核心是冒充可信角色誘導行動','不能僅以文法錯誤判斷真假'],'tags':['定義','社交工程','冒充']},
 {'id':'S02','organization':'FTC','title':'How To Recognize and Avoid Phishing Scams','url':'https://consumer.ftc.gov/articles/how-recognize-avoid-phishing-scams','topic':'辨識與應對','summary':'詐騙訊息可能假冒企業或機構，要求點擊連結、提供個資；應使用自己知道的官方聯絡管道查證，不要直接使用可疑訊息中的連結。','points':['核對寄件者、網域、請求內容與緊迫語氣','遭遇疑似釣魚時不要點可疑連結，改由官方管道聯絡'],'tags':['警訊','查證','防範']},
 {'id':'S03','organization':'Google','title':'Social Engineering (Phishing and Deceptive Sites)','url':'https://developers.google.com/search/docs/monitor-debug/security/social-engineering','topic':'網站偵測','summary':'假網站會透過模仿可信網站誘使使用者洩露密碼等敏感資料；Safe Browsing 對已辨識的欺騙性網站顯示警告。','points':['假登入頁是典型社交工程案例','瀏覽器警示是輔助保護，不等同所有新網站都已被偵測'],'tags':['假網站','瀏覽器','Safe Browsing']},
 {'id':'S04','organization':'Microsoft','title':'Protect yourself from online scams and attacks','url':'https://support.microsoft.com/en-us/support/protect-yourself-from-online-scams-and-attacks','topic':'防護工具','summary':'以更新軟體、防毒保護、瀏覽器反釣魚警告以及查驗來源降低受騙風險；Microsoft Defender SmartScreen 可以協助封鎖已知釣魚網站。','points':['保護工具是多層防禦的一部分','偵測結果不能取代人工查證'],'tags':['SmartScreen','保護','防禦']},
 {'id':'S05','organization':'FBI','title':'Stay Safe Online: Simple Tips for Adults','url':'https://www.fbi.gov/how-we-can-help-you/online-safety/stay-safe-online-simple-tips-for-adults','topic':'個人防護','summary':'面對疑似網路釣魚與惡意訊息，應透過另一種可靠方式聯絡對方；良好帳號安全習慣有助於降低風險。','points':['透過獨立管道驗證是重要策略','使用多重驗證增強帳號保護'],'tags':['獨立查證','MFA','個人防護']},
 {'id':'S06','organization':'NIST','title':'Phishing — Small Business Cybersecurity','url':'https://www.nist.gov/itl/smallbusinesscyber/guidance-topic/phishing','topic':'AI 時代的風險','summary':'生成式 AI 可能讓釣魚訊息更自然、更有說服力；只要要求點擊連結、下載、轉帳、登入或交出敏感資訊，就需要多一層確認。','points':['語句自然不等於真實','應依請求內容與來源多重判斷'],'tags':['生成式AI','風險','風險訊號']}
]
(root/'data'/'sources.json').write_text(json.dumps(sources,ensure_ascii=False,indent=2),encoding='utf-8')
chunks=[]
for s in sources:
 for i,point in enumerate([s['summary']]+s['points']):
  chunks.append({'chunk_id':f"{s['id']}-C{i+1}",'source_id':s['id'],'section':s['topic'],'text':point,'keywords':s['tags']})
(root/'data'/'wiki_index.json').write_text(json.dumps(chunks,ensure_ascii=False,indent=2),encoding='utf-8')
css='''
:root{color-scheme:dark;--bg:#091321;--panel:#111f32;--panel2:#17283d;--line:#2d4258;--text:#eaf1fb;--muted:#a0b3c9;--accent:#52d8c8;--yellow:#f8cb72}
*{box-sizing:border-box}body{margin:0;background:radial-gradient(circle at 85% -5%,#17395a 0%,transparent 36%),var(--bg);color:var(--text);font:16px/1.65 system-ui,-apple-system,'Noto Sans TC',sans-serif}a{color:var(--accent)}.wrap{max-width:1150px;margin:0 auto;padding:24px}.top{display:flex;align-items:center;justify-content:space-between;flex-wrap:wrap;gap:14px;border-bottom:1px solid var(--line);padding-bottom:18px}.brand{font-weight:800;letter-spacing:.06em}.nav{display:flex;gap:18px;flex-wrap:wrap}h1{font-size:clamp(32px,5vw,58px);line-height:1.16;margin:12px 0 22px}h2{font-size:clamp(23px,3vw,34px);line-height:1.24}h3{margin:0 0 10px}.eyebrow{color:var(--accent);font-size:12px;font-weight:800;letter-spacing:.17em;text-transform:uppercase}.lead{font-size:19px;color:#c7d8e7;max-width:860px}.hero{padding:64px 0 40px}.pill{display:inline-flex;align-items:center;border:1px solid var(--line);border-radius:30px;padding:6px 12px;color:var(--muted);font-size:12px}.actions{display:flex;gap:12px;flex-wrap:wrap;margin-top:24px}.btn,button{border:1px solid var(--line);background:var(--panel2);color:var(--text);border-radius:10px;padding:11px 16px;cursor:pointer;font:inherit;text-decoration:none}.btn.primary,button.primary{background:var(--accent);border-color:var(--accent);color:#072429;font-weight:800}.btn:hover,button:hover{filter:brightness(1.13)}.grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:17px}.card{background:rgba(17,31,50,.91);border:1px solid var(--line);border-radius:17px;padding:24px}.card p,.sub{color:var(--muted)}.tag{color:var(--accent);font-weight:700;font-size:12px}.muted{color:var(--muted)}.section{margin:48px 0}.search{width:100%;background:#0b1727;color:var(--text);border:1px solid #48617c;border-radius:11px;padding:15px;font:inherit;margin:12px 0 24px}.sources{display:grid;gap:15px}.source{border:1px solid var(--line);border-radius:14px;padding:19px;background:var(--panel)}.source h3{font-size:19px}.source ul{margin:6px 0}.source li{margin:5px 0}.index-row{display:grid;grid-template-columns:110px 1fr;gap:12px;margin:12px 0;border-bottom:1px solid var(--line);padding-bottom:12px}.footer{border-top:1px solid var(--line);padding:30px 0;margin-top:64px;color:var(--muted);font-size:13px}.tiny{font-size:13px;color:var(--muted)}.diagram{display:grid;gap:11px;max-width:720px}.node{border:1px solid #3e7080;padding:16px 20px;border-radius:12px;background:#12283a;text-align:center}.arrow{text-align:center;color:var(--accent);font-size:21px}.fork{display:grid;grid-template-columns:1fr 1fr;gap:12px}.fork>*{border:1px solid var(--line);padding:15px;border-radius:12px}.kpi{font-size:38px;font-weight:850;color:var(--accent)}table{width:100%;border-collapse:collapse}th,td{text-align:left;border-bottom:1px solid var(--line);padding:12px;vertical-align:top}th{color:var(--accent)}.tablewrap{overflow-x:auto}@media(max-width:760px){.grid{grid-template-columns:1fr}.fork{grid-template-columns:1fr}.wrap{padding:16px}.hero{padding-top:35px}.index-row{grid-template-columns:1fr}}
'''
(root/'assets'/'style.css').write_text(css,encoding='utf-8')
head='''<!doctype html><html lang="zh-Hant"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><meta name="description" content="可檢索的網路釣魚知識庫與互動教學簡報"><title>{title}</title><link rel="stylesheet" href="assets/style.css"></head><body><div class="wrap"><header class="top"><div class="brand">◈ PHISHING / LLM WIKI</div><nav class="nav"><a href="index.html">首頁</a><a href="wiki.html">Wiki 知識庫</a><a href="slides.html">教學簡報</a><a href="workflow.html">Graph／紀錄</a></nav></header>{body}<footer class="footer">LLM Wiki 教學作業 · 2026-11-22 · 資料來源：NIST / FTC / Google / Microsoft / FBI · 教學示例，並非真實詐騙偵測服務</footer></div></body></html>'''
def page(name,title,body): (root/name).write_text(head.format(title=title,body=body),encoding='utf-8')
page('index.html','AI 辨識詐騙｜LLM Wiki','''<main><section class="hero"><div class="eyebrow">A source-grounded learning experience</div><h1>AI 如何辨識<br><span style="color:var(--accent)">網路釣魚與詐騙訊息？</span></h1><p class="lead">從生活化案例出發，理解釣魚訊息的特徵、AI 輔助辨識的流程與限制。這份教學以六篇官方資安資料建立本地可查詢 Wiki，再將 Wiki 的知識點轉成互動簡報。</p><div class="actions"><a class="btn primary" href="slides.html">開始 10 頁教學 →</a><a class="btn" href="wiki.html">探索 Wiki</a><a class="btn" href="workflow.html">查看 Graph 與測試紀錄</a></div></section><section class="grid"><div class="card"><div class="kpi">06</div><h3>官方來源</h3><p>六篇整理成帶來源 ID 的條目，保留出處連結。</p></div><div class="card"><div class="kpi">18</div><h3>檢索片段</h3><p>每篇來源切分摘要與重點三段，提供關鍵字查詢。</p></div><div class="card"><div class="kpi">10</div><h3>教學投影片</h3><p>含情境練習、來源追溯、操作按鈕及鍵盤導覽。</p></div></section><section class="section card"><div class="eyebrow">Scope & honesty</div><h2>這個 Wiki 如何運作？</h2><p>本作品為可離線執行的「來源導向知識庫」原型：先人工確認官方資料，再將重點整理為結構化條目，透過瀏覽器內建搜尋進行檢索。簡報內容依條目設計並標註來源 ID。<strong>這不是已連線到外部 LLM API 的自動問答系統</strong>；若課堂要求特定 LLM Wiki 平台的真實 ingest，需要另外把這六篇資料匯入該平台。</p></section></main>''')
source_html=[]
for s in sources:
 source_html.append(f'''<article class="source" id="{s['id']}" data-search="{html.escape(' '.join([s['organization'],s['title'],s['summary'],*s['tags'],*s['points']]).lower(),quote=True)}"><div class="tag">{s['id']} · {s['organization']} · {s['topic']}</div><h3>{html.escape(s['title'])}</h3><p>{html.escape(s['summary'])}</p><ul>{''.join('<li>'+html.escape(p)+'</li>' for p in s['points'])}</ul><a href="{s['url']}" rel="noopener noreferrer" target="_blank">開啟官方原始資料 ↗</a></article>''')
wiki_body='''<main><section class="hero"><div class="eyebrow">Knowledge base / source traceability</div><h1>可搜尋的 Wiki 知識庫</h1><p class="lead">六篇權威來源，各自有來源 ID、濃縮摘要、教學重點和原始連結。可輸入「假網站」「AI」「查證」「MFA」等關鍵字。</p><input id="q" class="search" type="search" placeholder="搜尋 Wiki 條目或重點…" aria-label="搜尋 Wiki"><p id="count" class="tiny" aria-live="polite">顯示 6 / 6 篇來源</p></section><section class="sources" id="sources">'''+''.join(source_html)+'''</section><section class="section card"><h2>知識檢索流程</h2><p>使用者輸入問題 → 比對本地條目的標題、關鍵字、摘要與重點 → 回傳符合的來源 → 依原始連結核查。每一筆檢索內容都與來源 ID 綁定，因此簡報可以追溯到哪一篇資料。</p><p class="tiny">注意：搜尋功能是前端關鍵字過濾，不是語意向量檢索或即時 LLM 生成。</p></section></main><script>const q=document.getElementById('q'),cards=[...document.querySelectorAll('.source')],count=document.getElementById('count');q.addEventListener('input',()=>{let term=q.value.trim().toLowerCase(),n=0;cards.forEach(c=>{let ok=c.dataset.search.includes(term);c.hidden=!ok;if(ok)n++});count.textContent=`顯示 ${n} / ${cards.length} 篇來源`});</script>'''
page('wiki.html','Wiki 知識庫',wiki_body)
slides=[
 ('先學會停一下','AI 如何辨識網路釣魚？','看懂可疑訊息，不再只憑直覺點連結。',['今天會學會：什麼是釣魚、有哪些危險訊號、AI 怎麼輔助、以及如何安全查證。'],['S01','S02']),
 ('01 / 定義','什麼是網路釣魚？','看起來像真的，目的是讓你做錯事。',['釣魚是一種社交工程：假冒可信任機構或人物。','常見目的：取得密碼、信用卡資訊、付款，或誘導進入假網站。','重點不是訊息長得多專業，而是它要求你做什麼。'],['S01','S03']),
 ('02 / 生活情境','你收到這封「帳號停權」通知','範例訊息：您的帳號將於 10 分鐘後停權，請立即點連結驗證。',['可疑訊號 A：製造恐慌與時間壓力。','可疑訊號 B：把登入導向不明連結。','可疑訊號 C：以官方名義要求敏感資訊。'],['S02','S06']),
 ('03 / 看懂警訊','三個值得提高警覺的特徵','警訊是線索，不是單一證據。',['① 催促：立即操作、否則停權或罰款。','② 誘導：點擊未知連結、下載檔案、匯款。','③ 冒充：寄件者名稱像官方，但真實網域或請求不合理。'],['S02','S06']),
 ('04 / AI 的角色','AI 可以怎麼協助判斷？','把文字轉成可解釋的風險訊號。',['輸入：訊息文字與可安全取得的發送資訊。','分析：偵測緊急語氣、索取敏感資訊、可疑連結或冒充線索。','輸出：標註風險原因，提示使用者改走官方管道查證。','這是教學用的分析流程，不是已部署的 AI 分類器。'],['S01','S02','S06']),
 ('05 / AI 的限制','為什麼 AI 也可能判錯？','自然、流暢的文字也可能是詐騙。',['AI 可能誤判：真實通知也會有「立即」等字樣。','AI 可能漏判：生成式 AI 能寫出非常自然的詐騙文案。','沒有完整上下文時，模型無法保證寄件者或網站的真實性。','最重要：讓 AI 協助提醒，而不是直接取代查證。'],['S06','S02']),
 ('06 / 安全操作','收到疑似詐騙訊息怎麼辦？','停、查、保護。',['停：先不要點訊息內的連結或開啟附件。','查：自己打開官方 App／網站或撥打已知電話確認。','保護：開啟多重驗證、更新裝置與瀏覽器安全防護。','如果已輸入密碼，立即由官方網站修改密碼並採取帳戶保護措施。'],['S02','S04','S05']),
 ('07 / 保護機制','瀏覽器能幫上什麼忙？','安全警告是多一層防線。',['Google Safe Browsing 可對被辨識的欺騙性網站發出警告。','Microsoft SmartScreen 可協助攔截已知惡意或釣魚網站。','沒出現警告，不代表網站就一定安全。'],['S03','S04']),
 ('08 / 小測驗','看到這則訊息，你會怎麼做？','「物流異常！請於 15 分鐘內點網址補繳 25 元。」',['A. 直接點進去付錢，以免包裹退回。','B. 不點連結，開官方物流平台確認是否真的有訂單。','C. 把信用卡資料回覆給寄件者。'],['S02','S05']),
 ('09 / 重點回顧','三句話記住今天的重點','讓 AI 提醒你，把確認權留給自己。',['釣魚是利用冒充與誘導行動的社交工程。','AI 可輔助辨識風險，但輸出不是定論。','遇到可疑訊息，透過獨立官方管道確認。'],['S01','S02','S06'])]
js_slides=json.dumps([{'eyebrow':a,'title':b,'subtitle':c,'bullets':d,'refs':e} for a,b,c,d,e in slides],ensure_ascii=False)
slides_body='''<main><section class="slide-stage"><div class="slide-meta"><span id="chapter" class="eyebrow"></span><span id="progress" class="pill"></span></div><article id="slide" class="slide-card" aria-live="polite"><h1 id="stitle"></h1><p id="ssub" class="slide-sub"></p><ul id="bullets"></ul><div id="quiz" class="quiz" hidden><button data-answer="wrong">A · 立即付款</button><button data-answer="correct">B · 官方平台查證</button><button data-answer="wrong">C · 回覆信用卡</button><p id="feedback" class="feedback" aria-live="polite"></p></div><div class="slide-sources"><strong>來源：</strong><span id="refs"></span>　<a href="wiki.html">前往 Wiki 查證 ↗</a></div></article><div class="controls"><button id="prev" aria-label="上一頁">← 上一頁</button><div class="dots" id="dots"></div><button class="primary" id="next" aria-label="下一頁">下一頁 →</button></div><p class="tiny">可使用鍵盤 ← → 切換簡報 · 支援手機瀏覽 · 所有來源都可由 Wiki 回溯</p></section></main><style>.slide-stage{padding:24px 0}.slide-meta,.controls{display:flex;align-items:center;justify-content:space-between;gap:12px}.slide-card{background:linear-gradient(135deg,#15273b,#0e1c2e);border:1px solid #37556a;border-radius:24px;min-height:575px;padding:clamp(24px,5vw,65px);margin:15px 0 22px;display:flex;flex-direction:column}.slide-card h1{font-size:clamp(34px,5.3vw,66px);max-width:850px;margin:10px 0 10px}.slide-sub{font-size:clamp(19px,2.5vw,27px);color:var(--accent);margin:0 0 25px}.slide-card ul{font-size:clamp(17px,2vw,22px);line-height:1.7;list-style:none;padding:0;margin:4px 0 32px}.slide-card li{padding-left:25px;margin:11px 0;position:relative}.slide-card li:before{content:'◆';position:absolute;left:0;color:var(--accent);font-size:12px;top:8px}.slide-sources{margin-top:auto;border-top:1px solid #385267;padding-top:17px;color:var(--muted);font-size:13px}.slide-sources a{margin:0 5px}.dots{display:flex;gap:7px;flex-wrap:wrap;justify-content:center}.dot{width:9px;height:9px;border-radius:50%;background:#3e536a;border:0;padding:0}.dot.active{background:var(--accent);width:21px;border-radius:10px}.quiz{display:flex;flex-wrap:wrap;gap:10px}.quiz[hidden]{display:none}.quiz button{text-align:left}.feedback{width:100%;color:var(--yellow);font-weight:bold}@media(max-width:600px){.slide-card{min-height:650px}.controls{flex-wrap:wrap}.dots{order:3;width:100%}}</style><script>const slides=SLIDE_DATA;let at=0;const el=id=>document.getElementById(id);function show(n){at=Math.min(slides.length-1,Math.max(0,n));let s=slides[at];el('chapter').textContent=s.eyebrow;el('progress').textContent=(at+1)+' / '+slides.length;el('stitle').textContent=s.title;el('ssub').textContent=s.subtitle;el('bullets').innerHTML=s.bullets.map(t=>'<li>'+t+'</li>').join('');el('refs').innerHTML=s.refs.map(r=>'<a href="wiki.html#'+r+'">['+r+']</a>').join(' ');el('prev').disabled=at===0;el('next').textContent=at===slides.length-1?'回到第一頁 ↻':'下一頁 →';el('quiz').hidden=at!==8;el('feedback').textContent='';el('dots').innerHTML=slides.map((_,i)=>'<button class="dot '+(i===at?'active':'')+'" title="第'+(i+1)+'頁" aria-label="前往第'+(i+1)+'頁" data-i="'+i+'"></button>').join('');el('dots').querySelectorAll('button').forEach(b=>b.onclick=()=>show(+b.dataset.i));}el('prev').onclick=()=>show(at-1);el('next').onclick=()=>show((at+1)%slides.length);document.addEventListener('keydown',e=>{if(e.key==='ArrowRight')show((at+1)%slides.length);if(e.key==='ArrowLeft')show(at-1)});document.querySelectorAll('[data-answer]').forEach(b=>b.onclick=()=>{el('feedback').textContent=b.dataset.answer==='correct'?'答對了！請透過獨立官方管道確認，不要直接點訊息附上的連結。':'再想想：可疑訊息中的連結與付款要求不能直接相信。';});show(0);</script>'''.replace('SLIDE_DATA',js_slides)
page('slides.html','互動教學簡報',slides_body)
workflow='''<main><section class="hero"><div class="eyebrow">Iteration · traceability · validation</div><h1>Loop / Graph 設計與檢查紀錄</h1><p class="lead">採用「來源先行」的循環設計。來源不足或檢查失敗時回到前一步修正，而不是直接產生沒有可追溯證據的簡報。</p></section><section class="section"><h2>1. Graph 流程圖</h2><div class="diagram"><div class="node">① 討論範圍與教學對象：以初學者理解釣魚風險為目標</div><div class="arrow">↓</div><div class="node">② 取得 6 篇官方來源，核對來源 URL、主題與可信度</div><div class="arrow">↓</div><div class="node">③ Ingest：萃取摘要、重點、關鍵字，切成 18 個可搜尋片段</div><div class="arrow">↓</div><div class="node">④ 查詢 Wiki 並規劃 10 頁教學結構</div><div class="arrow">↓</div><div class="node">⑤ 檢查：正確性／來源 ID／初學者可讀性／敏感內容</div><div class="fork"><div>↺ <strong>未通過</strong><br>返回 ③ 或 ④ 修正內容，重跑檢查</div><div><strong>通過</strong> → ⑥ 產生 HTML 簡報</div></div><div class="arrow">↓</div><div class="node">⑦ 測試連結、頁面切換、搜尋與小測驗；有錯回 ⑥ 修正</div></div></section><section class="section"><h2>2. 哪些地方會重跑？</h2><div class="grid"><article class="card"><h3>來源 loop</h3><p>來源不可靠、URL 失效或重點沒有對應出處時，回到來源取得／整理節點。</p></article><article class="card"><h3>內容 loop</h3><p>簡報宣稱超出 Wiki、用語誤導或初學者看不懂時，先修改 Wiki 條目再重新產生該頁。</p></article><article class="card"><h3>介面 loop</h3><p>按鈕失效、投影片太擠或手機版排版溢出時，回到 HTML 結構與樣式節點修正。</p></article></div></section><section class="section"><h2>3. 實際執行與檢查紀錄</h2><p class="muted">以下記錄來自本地建置與程式化檢查；不是虛構的 LLM API 執行紀錄。執行者可用專案中的 <code>check.py</code> 重新驗證。</p><div class="tablewrap"><table><thead><tr><th>檢查項目</th><th>判準</th><th>本次結果</th></tr></thead><tbody><tr><td>來源 ingest</td><td>至少 5 篇、來源 ID 唯一、每篇有 URL</td><td>6 篇 / 6 個 ID</td></tr><tr><td>索引生成</td><td>每篇均分為摘要與兩個重點</td><td>18 個片段</td></tr><tr><td>來源對照</td><td>所有投影片引用的 ID 必須存在於 Wiki</td><td>待程式檢查，結果見 CHECK_REPORT</td></tr><tr><td>頁面完整</td><td>首頁、Wiki、簡報、Graph 均存在</td><td>待程式檢查，結果見 CHECK_REPORT</td></tr><tr><td>互動</td><td>前後頁、搜尋、答案回饋</td><td>以瀏覽器進行互動測試</td></tr></tbody></table></div><p><a class="btn" href="docs/CHECK_REPORT.txt">下載測試結果</a></p></section><section class="section card"><h2>4. 反思與修改</h2><p><strong>最容易出錯的節點：</strong>「整理重點 → 轉成簡報」的過程容易把推論說成確定事實，例如將「安全工具能攔截已知釣魚網站」過度簡化成「能辨識所有詐騙」。這是本作品最主要的<strong>風險節點</strong>，並非聲稱曾有 LLM 執行失敗次數統計。</p><p><strong>檢查前移：</strong>不等 HTML 完成才檢查；改在③ ingest 建立每個重點的來源 ID，⑤ 審稿時要求投影片必須具有來源 ID、釐清「可能」與「一定」的差別，再進入 HTML 生成。</p><p><strong>Workflow 調整：</strong>原流程「取得資料 → 摘要 → 產生簡報 → 最後查錯」改為「取得資料 → 有來源 ID 的 Wiki → 逐頁對照檢查 → 產生簡報 → 介面測試」。先消除知識錯誤，能減少後續重做畫面。</p></section></main>'''
page('workflow.html','Graph 流程與檢查',workflow)
(root/'docs'/'SLIDE_SOURCE_MAP.md').write_text('# 簡報與 Wiki 的來源對應\n\n'+'\n'.join(f'- 第{i+1}頁「{s[1]}」：'+', '.join(s[4]) for i,s in enumerate(slides))+'\n',encoding='utf-8')
(root/'data'/'slides.json').write_text(json.dumps(slides,ensure_ascii=False,indent=2),encoding='utf-8')
print('Generated 4 pages,',len(sources),'sources,',len(chunks),'chunks,',len(slides),'slides')
